import{_ as a,o,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"अध्याय 106 | स्तर परिमार्जन · संवेदना-मूल स्तर · लूटमारपक्ष बनाम सहजीवनपक्ष तुलना","description":"","frontmatter":{"title":"अध्याय 106 | स्तर परिमार्जन · संवेदना-मूल स्तर · लूटमारपक्ष बनाम सहजीवनपक्ष तुलना","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","路线对比"],"related":["04-掠夺式修炼体系批判","01-衡元宙核心世界观","14-修炼境界统一划分"]},"headers":[],"relativePath":"hi/106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"hi/106_模块1-感元境-掠夺派vs共生派对比.md"}'),d={name:"hi/106_模块1-感元境-掠夺派vs共生派对比.md"};function u(l,t,i,h,q,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="अध्याय-106-संवेदना-मूल-स्तर-लूटमारपक्ष-एवं-सहजीवनपक्ष-की-व्यवस्थागत-तुलना" tabindex="-1">अध्याय 106 | संवेदना-मूल स्तर: लूटमारपक्ष एवं सहजीवनपक्ष की व्यवस्थागत तुलना <a class="header-anchor" href="#अध्याय-106-संवेदना-मूल-स्तर-लूटमारपक्ष-एवं-सहजीवनपक्ष-की-व्यवस्थागत-तुलना" aria-label="Permalink to &quot;अध्याय 106 | संवेदना-मूल स्तर: लूटमारपक्ष एवं सहजीवनपक्ष की व्यवस्थागत तुलना&quot;">​</a></h1><blockquote><p>मॉड्यूल: मॉड्यूल एक · स्तरों का गहन परिमार्जन | आधार दस्तावेज़: 04, 01, 14</p></blockquote><h2 id="भूमिका-दो-साधना-युक्तियाँ-दो-प्रकार-के-ब्रह्माण्ड" tabindex="-1">भूमिका: दो साधना युक्तियाँ, दो प्रकार के ब्रह्माण्ड <a class="header-anchor" href="#भूमिका-दो-साधना-युक्तियाँ-दो-प्रकार-के-ब्रह्माण्ड" aria-label="Permalink to &quot;भूमिका: दो साधना युक्तियाँ, दो प्रकार के ब्रह्माण्ड&quot;">​</a></h2><p>संवेदना-मूल स्तर केवल साधना का प्रारंभ नहीं, विश्वदृष्टि का प्रथम चौराहा भी है: प्रथम ऊर्जा-अवशोषण से ही साधक द्वि-मार्ग पर खड़ा है—या तो &quot;मैं विश्व से लेता हूँ&quot;, या &quot;मैं विश्व के साथ बढ़ता हूँ&quot;। ये दो वाक्य निकट लगते हैं, पर दो सर्वथा भिन्न ब्रह्माण्ड की ओर ले जाते हैं: एक शिकारक्षेत्र जहाँ बलवान दुर्बल को खाता है; दूसरा जीवन-समुदाय जहाँ सब प्राणी साथ उत्तरते हैं।</p><p>यह लेख शिकारी साधना प्रणाली और लंगर सहजीवी सभ्यता की व्यवस्थागत तुलना प्रस्तुत करता है।</p><p>छः शीर्ष स्वयंसिद्ध स्वयं विभाजक रेखा हैं: अति-लूटमारवाद स्वयंसिद्ध &quot;लेना&quot; और &quot;बढ़ना&quot; को अलग करता है; दस हज़ार जाति गणतंत्र स्वयंसिद्ध &quot;केवल मेरी जाति&quot; और &quot;सब जातियाँ&quot; को अलग करता है; सामूहिक आयामी उन्नति स्वयंसिद्ध &quot;मैं अकेला उतरूँ&quot; और &quot;हम साथ उतरें&quot; को अलग करता है; कार्य-कारण आत्म-अनुशासन स्वयंसिद्ध &quot;ऋण अन्यत्र&quot; और &quot;मैं अपना फल भोगूँ&quot; को अलग करता है; नियम प्राथमिकता स्वयंसिद्ध &quot;मेरी सुविधा के नियम&quot; और &quot;स्थिर स्व-संगत नियम&quot; को अलग करता है। सभी प्राणियों के लिए सार्वभौमिक असीम समानता का नियम स्थापित करता है कि हर प्राणी मूलभूत असीम शक्ति सहज धारण करता है: आलसी निश्चित न्यूनतम असीम बनाए रखते हैं और युग से बहिष्कृत नहीं होंगे, परिश्रमी तथा किशोर सर्वोच्च उच्च स्तरों के असीम संचय कर सकते हैं। असीम मूल सबमें सहज; लूटमार युक्ति का &quot;केवल बलवान ही जीवित रहें&quot; ततः सिद्ध अमान्य।</p><h2 id="एक-व्यवस्थागत-तुलना-मुख्य-सारणी" tabindex="-1">एक. व्यवस्थागत तुलना मुख्य सारणी <a class="header-anchor" href="#एक-व्यवस्थागत-तुलना-मुख्य-सारणी" aria-label="Permalink to &quot;एक. व्यवस्थागत तुलना मुख्य सारणी&quot;">​</a></h2><table tabindex="0"><thead><tr><th>आयाम</th><th>लूटमारपक्ष</th><th>सहजीवनपक्ष (लंगर)</th></tr></thead><tbody><tr><td>ऊर्जा स्रोत</td><td>पराए मूल को निगलता है</td><td>विश्व-चक्र से लेता है, लौटाता है</td></tr><tr><td>दुर्बलों के प्रति दृष्टिकोण</td><td>प्राकृतिक छांट, दुर्बल मरें</td><td>सबके लिए रेलिंग, एक भी न छूटे</td></tr><tr><td>सीलिंग युक्ति</td><td>कब्रिस्तान पर एक शिखर</td><td>समग्र साथ उतरे</td></tr><tr><td>क्षितिज-काल</td><td>अभी सींचो, बाद में फेंको</td><td>द्वि-मुखी चक्र, धारणीय</td></tr><tr><td>जोखिम दृष्टिकोण</td><td>जोखिम छांकनी</td><td>जोखिम प्रबंधनीय समस्या</td></tr><tr><td>नैतिक आधार</td><td>बल ही धर्म</td><td>कार्य-कारण आत्म-अनुशासन</td></tr><tr><td>अंतिम गंतव्य</td><td>एक तारका-क्षेत्र का अधिपति</td><td>अति-बहुल संतुलित-लंगर स्तर</td></tr></tbody></table><h2 id="दो-लूटमारपक्ष-के-त्रुटि-सिद्धांत" tabindex="-1">दो. लूटमारपक्ष के त्रुटि-सिद्धांत <a class="header-anchor" href="#दो-लूटमारपक्ष-के-त्रुटि-सिद्धांत" aria-label="Permalink to &quot;दो. लूटमारपक्ष के त्रुटि-सिद्धांत&quot;">​</a></h2><ol><li>शून्य-योग त्रुटि-सिद्धांत: विश्वास है शक्ति स्थिर है, अतः लेने हेतु दूसरे से छीनना होगा—अज्ञान है कि विश्व-चक्र की ऊर्जा नवीकरणीय एवं विस्तारशील है।</li><li>प्राकृतिक छांट त्रुटि-सिद्धांत: विश्वास है दुर्बल छांटे जाने योग्य—अज्ञान है कि आलस्यपूर्ण न्यूनतम असीम मंदों को कुचले बिना साथ चलने देता है।</li><li>&quot;प्रबुद्ध लुटेरे&quot; त्रुटि-सिद्धांत: विश्वास है दयालु लुटेरा श्रेष्ठ लुटेरा—अज्ञान है कि लूटमार की संरचना स्वयं ही रोग है, लुटेरे का स्वभाव नहीं।</li></ol><h2 id="तीन-प्रबुद्ध-लुटेरा-और-ऐतिहासिक-प्रतिगमन" tabindex="-1">तीन. &quot;प्रबुद्ध लुटेरा&quot; और ऐतिहासिक प्रतिगमन <a class="header-anchor" href="#तीन-प्रबुद्ध-लुटेरा-और-ऐतिहासिक-प्रतिगमन" aria-label="Permalink to &quot;तीन. &quot;प्रबुद्ध लुटेरा&quot; और ऐतिहासिक प्रतिगमन&quot;">​</a></h2><p>तथाकथित प्रबुद्ध लुटेरा—अर्थात् वह बलवान जो अकारण नहीं मारता, दुर्बलों के साथ &quot;कुछ बाँटता&quot; है, स्वयं को परोपकारी कहता है—लूटमारपक्ष का सबसे खतरनाक आत्म-भ्रम है। दयालु शिकारी अभी भी शिकारी है; उसकी दया केवल शिकार-प्रबंधन का परिशोधन है। इतिहास बार-बार दिखाता है कि लूटमार प्रणाली का &quot;प्रबुद्ध&quot; युग सदा प्रतिगमन की पूर्वसंध्या होता है: शिकारक्षेत्र समाप्त होते ही, &quot;परोपकारी&quot; बलवान सर्वप्रथम अपने ही लोगों के विरुद्ध फिरते हैं।</p><h2 id="चार-धार्मिक-गुंडा-चुने-हुओं-के-लिए-चेतावनी" tabindex="-1">चार. धार्मिक गुंडा: &quot;चुने हुओं&quot; के लिए चेतावनी <a class="header-anchor" href="#चार-धार्मिक-गुंडा-चुने-हुओं-के-लिए-चेतावनी" aria-label="Permalink to &quot;चार. धार्मिक गुंडा: &quot;चुने हुओं&quot; के लिए चेतावनी&quot;">​</a></h2><p>सहजीवनपक्ष यह ढोंग नहीं करता कि उसका अपना पक्ष परिपूर्ण है। सबसे छलावा प्ररूप है &quot;धार्मिक गुंडा&quot;: जो न्याय का चोगा पहने फिर भी लूटता है, कहता है &quot;यह मैं सहजीवन के लिए करता हूँ&quot;, जबकि अपनी प्रगति हेतु दूसरों को सींचता है।</p><p>इसी ब्रह्माण्ड के नायक लिन हाओ को कसौटी रूप में लीजिए: उसका पथ शिकारक्षेत्र में सर्वबलवान बनना नहीं, वरन् यह सिद्ध करना है कि बलवान उत्तरते हुए भी दुर्बलों को घर लौटने का मार्ग दे सकता है। हर बार जब वह &quot;मैं विशिष्ट हूँ, अतः नियम मुझपर लागू नहीं&quot; कहने को उद्यत हो, ठीक वही क्षण है जब शीघ्र-पथ अंतरंग राक्षस दस्तक देता है—यही वह अंतरंग रेखा है जिसे सहजीवनपक्ष का हर साधक अवश्य धारण करे।</p><h2 id="पाँच-पाँच-मूल-स्थल" tabindex="-1">पाँच. पाँच मूल स्थल <a class="header-anchor" href="#पाँच-पाँच-मूल-स्थल" aria-label="Permalink to &quot;पाँच. पाँच मूल स्थल&quot;">​</a></h2><ul><li>ऊर्जा-स्तर अपव्यय विरोध: लूटमारपक्ष का &quot;बलवान दुर्बल को खाए&quot; किसी भी युद्ध से अधिक विकास-संभावना व्यर्थ करता है; सहजीवनपक्ष का द्वि-मुखी चक्र ही सच्ची उच्च-दक्षता है।</li><li>लूटमार विरोध: मुख्य सारणी की हर पंक्ति लाल रेखा है जिसे सहजीवनपक्ष लाँघेगा नहीं।</li><li>तांग लुआऊ सीलिंग तुलना: लूटमारपक्ष का सीलिंग कब्रिस्तान पर एक अधिपति; सहजीवनपक्ष का सीलिंग संपूर्ण ब्रह्माण्ड को उठा ले।</li><li>हाजारो जाति पूर्ण आवरण: मुख्य सारणी ऊर्जा-स्रोत से अंतिम गंतव्य तक हर आयाम आच्छादित, कोई अंधकोण नहीं।</li><li>अति-बहुलवाद पूर्ण उन्मुक्ति: तुलना स्वयं खुला प्रमाण है—लूटमारपक्ष इसे छापने का साहस नहीं करता, क्योंकि हर आयाम उसकी स्वयं की क्षुद्रता उजागर करता है।</li></ul><h2 id="उपसंहार" tabindex="-1">उपसंहार <a class="header-anchor" href="#उपसंहार" aria-label="Permalink to &quot;उपसंहार&quot;">​</a></h2><p>सारणी को अलंकार की आवश्यकता नहीं; दो स्तंभ स्वयं बोलते हैं। संवेदना-मूल स्तर में साधक जो प्रथम अवशोषण चुनता है, वह शेष जीवन में किस स्तंभ में खड़ा होगा, यह तय करता है—यही कारण कि यह तुलना संपूर्ण पुस्तकालय के सर्वप्रथम रखी गई है: प्रत्येक पाठक पथ चुनने से पूर्व देख ले कि वह किस ब्रह्माण्ड में प्रवेश करने जा रहा है।</p><h2 id="संबंध" tabindex="-1">संबंध <a class="header-anchor" href="#संबंध" aria-label="Permalink to &quot;संबंध&quot;">​</a></h2><ul><li>संबंधित दस्तावेज़: <a href="./04-掠夺式修炼体系批判.html">04-शिकारी साधना प्रणाली की आलोचना</a> · <a href="./01-衡元宙核心世界观.html">01-हेंग युआनझोउ मूल विश्वदृष्टि</a> · <a href="./14-修炼境界统一划分.html">14-साधना स्तरों का एकीकृत विभाजन</a></li><li>आधिकारिक साइट: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',21)])])}const c=a(d,[["render",u]]);export{_ as __pageData,c as default};
